self.KB_CONTENT["card:797858"]={"id":"card:797858","ty":"card","sourceId":"797858","title":"請問一個商品是否可設定多個售價管制下限率，供不同業務使用?","ver":"GP4以上","topic":"客戶","keywords":["客戶","商品","業務"],"y":"error","answer":"目前無法依不同使用者設定不同的售價，但可依不同客戶設定不同售價","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
