self.KB_CONTENT["card:750561"]={"id":"card:750561","ty":"card","sourceId":"750561","title":"『客戶帳齡分析表』的作業目的為何？","ver":"iGP","topic":"分析表","keywords":["分析表","客戶","應收","帳款"],"y":"explain","answer":"將某一特定時點各客戶之應收帳款資料，依照部門別及客戶代號的順序分析其帳齡，以瞭解客戶別應收帳款未沖銷部份之帳齡，列印成表。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
