self.KB_CONTENT["card:751896"]={"id":"card:751896","ty":"card","sourceId":"751896","title":"『立沖帳目明細表』中的『選擇結案狀態』為何？","ver":"iGP","topic":"立沖帳目","keywords":["立沖帳目","明細表","狀態","結案"],"y":"other","answer":"* 區分N.未結案、y.指定結案、Y.自動結案及全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
