self.KB_CONTENT["field:753689"]={"id":"field:753689","ty":"field","sourceId":"753689","title":"付款條件","ver":"iGP","topic":"","keywords":[],"job":"客戶訂單建立作業","code":"TC042","answer":"* 預設「客戶基本資料」之資料，亦可修改，點選(icon)或[F2]付款條件代號查詢。","file":"fields.jsonl"};
